// Anything sitting unreviewed for too long. The API has no "stale" endpoint on
// purpose - this is a policy question, and policy that changes often is better
// expressed here than baked into the backend.
//
// Two rules live here:
//   1. Back off. Chase at 30m, 1h, 2h, 4h, 8h - then stop. Chasing every 15
//      minutes forever teaches people to ignore the chase, and a reminder
//      nobody reads is worse than no reminder, because it looks like coverage.
//   2. Most urgent first, so a HIGH ticket is not queued behind a LOW one.

// Must match the schedule trigger. A milestone counts as due when it falls in
// the window this run covers, and that window is only correct if it is the
// same as the gap between runs. Change the trigger interval without changing
// this and one milestone lands in several consecutive windows, which is the
// every-15-minutes spam this was written to stop.
const RUN_EVERY_MINUTES = 15;
const CHASE_AT_MINUTES = [30, 60, 120, 240, 480];
const RANK = { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3 };
const LAST_CHASE = CHASE_AT_MINUTES[CHASE_AT_MINUTES.length - 1];

const now = Date.now();
const stale = [];

for (const item of $input.all()) {
  const t = item.json;
  if (t.status !== 'AWAITING_APPROVAL') continue;

  const waitingMinutes = Math.round((now - Date.parse(t.updated_at)) / 60000);

  // Chase on the run that crosses a milestone, not on every run after it.
  // Deliberately stateless - there is no record of what was chased last time,
  // only arithmetic on how long this ticket has been waiting. That means a
  // missed run costs a chase rather than causing a duplicate one, which is the
  // safer direction to fail in for something that writes to a ticket.
  const due = CHASE_AT_MINUTES.some(
    (m) => m > waitingMinutes - RUN_EVERY_MINUTES && m <= waitingMinutes,
  );
  if (!due) continue;

  stale.push({
    json: {
      ticket_id: t.id,
      subject: t.subject,
      priority: t.priority,
      waiting_minutes: waitingMinutes,
      // Past the last milestone nothing matches and the chasing stops on its
      // own. Whoever should have acted has had eight hours; more noise will not
      // help. Escalating instead is a service desk decision, and it changes
      // ticket state, so it belongs behind the API rather than in here.
      final_chase: waitingMinutes >= LAST_CHASE,
    },
  });
}

// Most urgent first, longest wait first within a priority. The batching below
// preserves this order, so this is what decides who gets chased in batch one.
// Anything with a missing or unrecognised priority sorts last rather than
// throwing - a null priority means analysis never finished, and that is a
// different problem from being slow to approve.
stale.sort(
  (a, b) =>
    (RANK[a.json.priority] ?? 99) - (RANK[b.json.priority] ?? 99) ||
    b.json.waiting_minutes - a.json.waiting_minutes,
);

// Returning an empty array stops the branch here - downstream nodes simply do
// not run, so there is no "if anything found" node to write.
return stale;
